<?php
declare(strict_types=1);
function personContacts(array $b):array{
 $email=mb_strtolower(trim((string)($b['email']??'')));if(strlen($email)>190||$email&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new Fault('E-mail de contato inválido.');$out=['email'=>$email];foreach(['phone','alternatePhone'] as $key){$v=trim((string)($b[$key]??''));if(strlen($v)>30||$v&&!preg_match('/^[0-9+() .-]+$/',$v))throw new Fault('Telefone de contato inválido.');$out[$key]=$v;}
 $address=[];foreach(['postalCode'=>9,'street'=>160,'number'=>20,'complement'=>120,'district'=>100,'city'=>100,'state'=>2] as $key=>$max){$v=trim((string)($b[$key]??''));if(mb_strlen($v)>$max)throw new Fault('Campo de endereço muito longo.');$address[$key]=$v;}
 if(implode('',$address)!==''){foreach(['street','number','district','city','state','postalCode'] as $key)need($address[$key],'endereço: '.$key,160);$cep=preg_replace('/\D/','',$address['postalCode']);if(strlen($cep)!==8||!preg_match('/^\d{5}-?\d{3}$/',$address['postalCode']))throw new Fault('CEP inválido.');$uf=strtoupper($address['state']);if(!in_array($uf,explode(' ','AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'),true))throw new Fault('UF do endereço inválida.');$address['postalCode']=substr($cep,0,5).'-'.substr($cep,5);$address['state']=$uf;$out['residentialAddress']=$address;$out['address']=$address['street'].', '.$address['number'].($address['complement']?' · '.$address['complement']:'').' · '.$address['district'].' · '.$address['city'].'/'.$uf.' · CEP '.$address['postalCode'];}else{$out['residentialAddress']=null;$out['address']='';}return $out;
}
function updatePersonContacts(array $u,array $b):array{fullManager($u);$p=linkFor($u,$b['linkId']??'');if($p['version']!==($b['version']??null))throw new Fault('Cadastro alterado. Atualize antes de salvar.',409);$data=personContacts($b['data']??[]);foreach(records($u['tenant'],'links') as $link)if($link['personId']===$p['personId']){$details=$data;if(!$details['residentialAddress'])$details['address']=$link['address']??'';$link=array_replace($link,$details);updateLink($u,$link,$link['version'],'person.contacts.update');}return ['ok'=>true];}
